// ── WALLED GARDEN WALK — Vovó Maristela & Olivia ──

svg += `<defs>
  <linearGradient id="lg-wgw" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0E1420' : '#7898B0'}"/>
    <stop offset="40%" stop-color="${isN ? '#141E2A' : '#8AA8BC'}"/>
