</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-wgw)"/>`;

// ── Clouds (soft, partly cloudy Scottish spring) ──
for (let i = 0; i < 7; i++) {
  const ccx = (w * 0.02 + i * w * 0.18 + mt * 3) % (w + 100) - 50;
  const ccy = h * 0.05 + Math.sin(i * 1.8) * h * 0.04;
  const ccr = 30 + Math.sin(i * 2.1) * 12;
  const cop = isN ? 0.15 : 0.5 + Math.sin(i * 0.8) * 0.12;
  svg += `<ellipse cx="${ccx}" cy="${ccy}" rx="${ccr}" ry="${ccr * 0.35}" fill="#FFF" opacity="${cop}"/>`;
  svg += `<ellipse cx="${ccx - ccr * 0.3}" cy="${ccy + 2}" rx="${ccr * 0.55}" ry="${ccr * 0.25}" fill="#FFF" opacity="${cop * 0.8}"/>`;
}
// Blue patches showing through
if (!isN) {
  svg += `<ellipse cx="${w * 0.7}" cy="${h * 0.06}" rx="${w * 0.08}" ry="${h * 0.04}" fill="#6A9AC0" opacity="0.15"/>`;
}

// ═══ GARDEN LAYOUT ═══

// ── Lawn (left and right of central path) ──
svg += `<rect x="0" y="${bY - 25}" width="${w}" height="${h - bY + 25}" fill="${sc.ground}"/>`;
// Lawn texture variation
for (let i = 0; i < 15; i++) {
  const gx = w * (i / 15);
  const gy = bY - 10 + Math.sin(i * 1.7) * 8;
  svg += `<ellipse cx="${gx}" cy="${gy}" rx="18" ry="5" fill="#6A9A5A" opacity="0.15"/>`;
}

// ── RED GRAVEL PATH (central, running into distance — perspective) ──
const pathNearL = w * 0.35, pathNearR = w * 0.65;
const pathFarL = w * 0.46, pathFarR = w * 0.54;
const pathFarY = bY - 70;
svg += `<polygon points="${pathNearL},${bY+30} ${pathNearR},${bY+30} ${pathFarR},${pathFarY} ${pathFarL},${pathFarY}" fill="#B87A60" stroke="#A06A50" stroke-width="${ol * 0.3}"/>`;
// Path texture (tiny gravel dots)
for (let i = 0; i < 40; i++) {
  const t = i / 40;
  const gpx = pathNearL + (pathFarL - pathNearL) * t + (pathNearR - pathNearL - (pathFarR - pathFarL) * t) * (Math.sin(i * 71.3) * 0.5 + 0.5) * (1 - t * 0.5);
  const gpy = bY + 30 - t * (bY + 30 - pathFarY);
  const gpr = 0.5 + (1 - t) * 0.5;
  svg += `<circle cx="${gpx}" cy="${gpy}" r="${gpr}" fill="#C08A70" opacity="0.3"/>`;
}
// Path edging (stone kerbs)
svg += `<line x1="${pathNearL}" y1="${bY+30}" x2="${pathFarL}" y2="${pathFarY}" stroke="#C0B8A8" stroke-width="2"/>`;
svg += `<line x1="${pathNearR}" y1="${bY+30}" x2="${pathFarR}" y2="${pathFarY}" stroke="#C0B8A8" stroke-width="2"/>`;

// ═══ BOX HEDGES (geometric patterns) ═══
// Left garden beds
const hedgeColor = '#2A5A22';
const hedgeStroke = '#1A4A18';

// Left hedges (geometric shapes in perspective)
for (let row = 0; row < 3; row++) {
  const t = row / 4;
  const hy = bY - 5 - row * 18;
  const hscale = 1 - t * 0.4;
  const hleft = pathNearL - 10 - row * 3;
  // Rectangle hedge shapes
  for (let i = 0; i < 2; i++) {
    const hx = w * 0.05 + i * (hleft * 0.4) * hscale;
    const hw3 = 35 * hscale;
    const hh3 = 10 * hscale;
    svg += `<rect x="${hx}" y="${hy - hh3}" width="${hw3}" height="${hh3}" rx="2" fill="${hedgeColor}" stroke="${hedgeStroke}" stroke-width="${ol * 0.4 * hscale}"/>`;
    // Top foliage (rounded)
    svg += `<ellipse cx="${hx + hw3 / 2}" cy="${hy - hh3}" rx="${hw3 / 2 + 1}" ry="${3 * hscale}" fill="#3A6A32" opacity="0.6"/>`;
  }
}
// Right hedges (mirror)
for (let row = 0; row < 3; row++) {
  const t = row / 4;
  const hy = bY - 5 - row * 18;
  const hscale = 1 - t * 0.4;
  for (let i = 0; i < 2; i++) {
    const hx = pathNearR + 10 + row * 3 + i * 30 * hscale;
    const hw3 = 35 * hscale;
    const hh3 = 10 * hscale;
    svg += `<rect x="${hx}" y="${hy - hh3}" width="${hw3}" height="${hh3}" rx="2" fill="${hedgeColor}" stroke="${hedgeStroke}" stroke-width="${ol * 0.4 * hscale}"/>`;
    svg += `<ellipse cx="${hx + hw3 / 2}" cy="${hy - hh3}" rx="${hw3 / 2 + 1}" ry="${3 * hscale}" fill="#3A6A32" opacity="0.6"/>`;
  }
}

// ── Tall back hedges (deep green wall along the back) ──
const backHY = pathFarY + 5;
svg += `<rect x="${w * 0.1}" y="${backHY - 20}" width="${w * 0.8}" height="20" rx="2" fill="#1A4A18" stroke="#0E3A0E" stroke-width="${ol * 0.5}"/>`;
svg += `<ellipse cx="${w * 0.5}" cy="${backHY - 20}" rx="${w * 0.4}" ry="4" fill="#2A5A22" opacity="0.5"/>`;

// ═══ GLASSHOUSE (behind the hedges) ═══
const ghX = w * 0.38, ghY = backHY - 25;
const ghW = w * 0.24, ghH = 22;
svg += `<rect x="${ghX}" y="${ghY - ghH}" width="${ghW}" height="${ghH}" fill="rgba(180,210,220,0.25)" stroke="#AAA" stroke-width="${ol * 0.5}"/>`;
// Glass panes
for (let i = 0; i < 6; i++) {
  const gpx = ghX + i * (ghW / 6);
  svg += `<line x1="${gpx}" y1="${ghY - ghH}" x2="${gpx}" y2="${ghY}" stroke="#AAA" stroke-width="0.5" opacity="0.5"/>`;
}
svg += `<line x1="${ghX}" y1="${ghY - ghH / 2}" x2="${ghX + ghW}" y2="${ghY - ghH / 2}" stroke="#AAA" stroke-width="0.5" opacity="0.5"/>`;
// Peaked roof
svg += `<polygon points="${ghX},${ghY - ghH} ${ghX + ghW / 2},${ghY - ghH - 10} ${ghX + ghW},${ghY - ghH}" fill="rgba(180,210,220,0.2)" stroke="#AAA" stroke-width="${ol * 0.4}"/>`;
// Glass reflections
svg += `<line x1="${ghX + 5}" y1="${ghY - ghH + 3}" x2="${ghX + 12}" y2="${ghY - 8}" stroke="rgba(220,240,255,0.15)" stroke-width="1.5"/>`;

// ═══ TREES (bare / early spring, background) ═══
const treeData = [[w*0.02,80],[w*0.12,65],[w*0.25,55],[w*0.6,50],[w*0.78,70],[w*0.9,60],[w*0.96,75]];
for (let t = 0; t < 7; t++) {
  const ttx = treeData[t][0];
  const tth = treeData[t][1];
  const tby = backHY - 18;
  const tsw = Math.sin(mt * 0.3 + t * 1.1) * 1.5;
  // Some trees are bare, some have early spring foliage
  const hasLeaves = t === 3 || t === 5 || t === 6;
  svg += `<line x1="${ttx}" y1="${tby}" x2="${ttx + tsw}" y2="${tby - tth}" stroke="#5A4A3A" stroke-width="${3 + Math.sin(t) * 1}" stroke-linecap="round"/>`;
  for (let b = 0; b < 4; b++) {
    const bh = tby - tth * (0.4 + b * 0.15);
    const bDir = (b % 2 === 0 ? 1 : -1);
    const bLen = 10 + Math.sin(b * 2.7) * 5;
    const bsw2 = Math.sin(mt * 0.5 + t * 0.8 + b * 0.6) * 1.5;
    svg += `<path d="M${ttx + tsw * (0.5 + b * 0.15)} ${bh} Q${ttx + bDir * bLen * 0.6 + bsw2} ${bh - 4} ${ttx + bDir * bLen + bsw2} ${bh - 6}" fill="none" stroke="#5A4A3A" stroke-width="${1.5}" stroke-linecap="round"/>`;
  }
  if (hasLeaves) {
    for (let c = 0; c < 3; c++) {
      const lcx = ttx + Math.sin(c * 1.5 + t) * 12 + tsw;
      const lcy = tby - tth - 2 + Math.cos(c * 1.2) * 8;
      const lcr = 8 + Math.sin(c * 2.3) * 3;
      svg += `<circle cx="${lcx}" cy="${lcy}" r="${lcr}" fill="${t === 6 ? '#3A7A3A' : '#5A9A4A'}" opacity="0.55"/>`;
    }
  }
}

// ── Stone wall (far background) ──
svg += `<rect x="${w * 0.7}" y="${backHY - 35}" width="${w * 0.3}" height="12" fill="#8A8070" stroke="#6A6050" stroke-width="${ol * 0.3}" opacity="0.4"/>`;

// ── Planting beds (green plants between hedges) ──
for (let i = 0; i < 8; i++) {
  const pbx = w * 0.08 + i * w * 0.11;
  const pby = bY - 10 + Math.sin(i * 1.5) * 5;
  if (pbx < pathNearL - 15 || pbx > pathNearR + 15) {
    const psw = Math.sin(mt * 0.8 + i * 0.9) * 1.5;
    svg += `<ellipse cx="${pbx}" cy="${pby}" rx="6" ry="4" fill="#4A8A3A" opacity="0.5"/>`;
    for (let j = 0; j < 3; j++) {
      svg += `<line x1="${pbx - 3 + j * 3}" y1="${pby}" x2="${pbx - 3 + j * 3 + psw}" y2="${pby - 6 - Math.sin(j) * 3}" stroke="#3A7A2A" stroke-width="1" stroke-linecap="round" opacity="0.5"/>`;
    }
  }
}

// ═══ CHARACTERS ═══

// ── VOVÓ MARISTELA (pushing the buggy, right side of path) ──
const mX = w * 0.58, mY = bY + 10;

// Legs (light jeans)
svg += `<line x1="${mX - 3}" y1="${mY + 2}" x2="${mX - 5}" y2="${mY + 22}" stroke="#8AB0D0" stroke-width="4" stroke-linecap="round"/>`;
svg += `<line x1="${mX + 3}" y1="${mY + 2}" x2="${mX + 6}" y2="${mY + 22}" stroke="#8AB0D0" stroke-width="4" stroke-linecap="round"/>`;
// White sneakers
svg += `<ellipse cx="${mX - 5}" cy="${mY + 23}" rx="4" ry="2" fill="#F0F0F0" stroke="#DDD" stroke-width="0.5"/>`;
svg += `<ellipse cx="${mX + 6}" cy="${mY + 23}" rx="4" ry="2" fill="#F0F0F0" stroke="#DDD" stroke-width="0.5"/>`;
// Body (black puffer jacket)
svg += `<rect x="${mX - 10}" y="${mY - 22}" width="20" height="24" rx="4" fill="#1A1A1A" stroke="#0A0A0A" stroke-width="${ol * 0.4}"/>`;
// Puffer jacket quilting lines
for (let i = 0; i < 4; i++) {
  svg += `<line x1="${mX - 9}" y1="${mY - 18 + i * 6}" x2="${mX + 9}" y2="${mY - 18 + i * 6}" stroke="#2A2A2A" stroke-width="0.5" opacity="0.4"/>`;
}
// Arms
svg += `<line x1="${mX + 10}" y1="${mY - 15}" x2="${mX + 18}" y2="${mY - 5}" stroke="#1A1A1A" stroke-width="4" stroke-linecap="round"/>`;
// Left hand holding coffee cup
svg += `<line x1="${mX - 10}" y1="${mY - 15}" x2="${mX - 16}" y2="${mY - 10}" stroke="#1A1A1A" stroke-width="4" stroke-linecap="round"/>`;
// COFFEE CUP!
svg += `<rect x="${mX - 19}" y="${mY - 16}" width="6" height="9" rx="1" fill="#C8A878" stroke="#A08858" stroke-width="0.5"/>`;
svg += `<rect x="${mX - 20}" y="${mY - 17}" width="8" height="3" rx="1" fill="#E8D8B8"/>`;
// Coffee steam
for (let i = 0; i < 3; i++) {
  const stx2 = mX - 16 + Math.sin(mt * 1.5 + i * 1.1) * 2;
  const sty2 = mY - 18 - i * 4;
  svg += `<path d="M${stx2} ${sty2} Q${stx2 + 2} ${sty2 - 2} ${stx2} ${sty2 - 4}" fill="none" stroke="rgba(255,255,255,${0.15 - i * 0.04})" stroke-width="1" stroke-linecap="round"/>`;
}
// Head
svg += `<circle cx="${mX}" cy="${mY - 27}" r="7" fill="#E8C8A8" stroke="#D0B090" stroke-width="${ol * 0.3}"/>`;
// Hair (pulled back, dark)
svg += `<path d="M${mX - 6} ${mY - 32} Q${mX} ${mY - 36} ${mX + 6} ${mY - 32}" fill="#3A2A1A" stroke="none"/>`;
svg += `<path d="M${mX + 4} ${mY - 30} Q${mX + 8} ${mY - 26} ${mX + 6} ${mY - 22}" fill="none" stroke="#3A2A1A" stroke-width="2" stroke-linecap="round"/>`;
// Glasses!
svg += `<circle cx="${mX - 2}" cy="${mY - 27}" r="2.5" fill="none" stroke="#8A7A6A" stroke-width="0.8"/>`;
svg += `<circle cx="${mX + 3}" cy="${mY - 27}" r="2.5" fill="none" stroke="#8A7A6A" stroke-width="0.8"/>`;
svg += `<line x1="${mX + 0.5}" y1="${mY - 27}" x2="${mX + 0.5}" y2="${mY - 27}" stroke="#8A7A6A" stroke-width="0.5"/>`;
// Smile
svg += `<path d="M${mX - 2} ${mY - 25} Q${mX} ${mY - 23} ${mX + 3} ${mY - 25}" fill="none" stroke="#8A6A5A" stroke-width="0.8"/>`;

// ── BUGGY (Joie, green hood, dark body) ──
const bgX = mX + 15, bgY = mY + 5;
// Wheels
svg += `<circle cx="${bgX - 8}" cy="${bgY + 12}" r="4" fill="#222" stroke="#111" stroke-width="0.5"/>`;
svg += `<circle cx="${bgX + 10}" cy="${bgY + 12}" r="4" fill="#222" stroke="#111" stroke-width="0.5"/>`;
