// Frame
svg += `<line x1="${bgX - 8}" y1="${bgY + 12}" x2="${bgX}" y2="${bgY - 2}" stroke="#222" stroke-width="2"/>`;
svg += `<line x1="${bgX + 10}" y1="${bgY + 12}" x2="${bgX + 5}" y2="${bgY - 2}" stroke="#222" stroke-width="2"/>`;
// Seat (dark grey)
svg += `<rect x="${bgX - 5}" y="${bgY - 5}" width="14" height="12" rx="3" fill="#2A2A2A" stroke="#1A1A1A" stroke-width="1"/>`;
// Green hood (teal/sage green, like the Joie)
svg += `<path d="M${bgX - 5} ${bgY - 8} Q${bgX + 2} ${bgY - 20} ${bgX + 12} ${bgY - 8}" fill="#6A9A8A" stroke="#5A8A7A" stroke-width="1"/>`;
// Sheepskin liner peek
