// Handle bar
svg += `<path d="M${bgX + 5} ${bgY - 2} Q${bgX + 10} ${bgY - 12} ${mX + 18} ${mY - 5}" fill="none" stroke="#2A2A2A" stroke-width="2" stroke-linecap="round"/>`;

// ── Distant people on the path (tiny silhouettes) ──
for (let i = 0; i < 3; i++) {
  const dpx = w * 0.48 + Math.sin(i * 2.1) * 5;
  const dpy = pathFarY + 10 + i * 5;
  const dps = 0.4 + i * 0.1;
  svg += `<ellipse cx="${dpx}" cy="${dpy - 4 * dps}" rx="${2 * dps}" ry="${4 * dps}" fill="#4A4A4A" opacity="0.3"/>`;
  svg += `<circle cx="${dpx}" cy="${dpy - 9 * dps}" r="${1.5 * dps}" fill="#5A5A5A" opacity="0.3"/>`;
}

// ── Night mode ──
if (isN) {
  svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="rgba(0,0,20,0.3)"/>`;
  svg += `<circle cx="${w * 0.8}" cy="${h * 0.08}" r="12" fill="#EDE8DF" opacity="0.7"/>`;
  svg += `<circle cx="${w * 0.8 + 4}" cy="${h * 0.08 - 3}" r="10" fill="#0E1420" opacity="0.85"/>`;
  for (let i = 0; i < 15; i++) {
    const stx = (Math.sin(i * 93.7 + 2.1) * 0.5 + 0.5) * w;
    const sty2 = (Math.sin(i * 217.3 + 5.7) * 0.5 + 0.5) * h * 0.25;
    svg += `<circle cx="${stx}" cy="${sty2}" r="0.5" fill="#FFF" opacity="${0.3 + Math.sin(mt + i) * 0.2}"/>`;
  }
} else {
  // Diffused sunlight through clouds
  svg += `<ellipse cx="${w * 0.55}" cy="${h * 0.08}" rx="${w * 0.1}" ry="${h * 0.04}" fill="#FFF" opacity="0.05"/>`;
}
